from pathlib import Path
import json,sys,hashlib
sys.path.insert(0,'tests')
from test_mobile_rendering import html
from playwright.sync_api import sync_playwright
source=Path('assets/game.js').read_text();base=Path('experimental/worker/model.generated.js').read_text();bridge=''.join(Path('experimental/worker/'+n).read_text() for n in ['runtime-guard.js','archive-endpoint.js','real-view-bridge.js'])
extra='''\nlet hookMap=null;registerWorkerRouteModule({version:1,id:'hook-test',runtime:{capture:()=>hookMap,restore:x=>{hookMap=x;}},operations:{
 view:{mode:'preview',fields:{},execute(p,ctx){civicCalendarView();ctx.present({kind:'policy-draft',values:{minWage:14}});ctx.openPanel('policies');ctx.present({kind:'focus-policy',key:'minWage'});ctx.present({kind:'overlay',value:'roads'});ctx.present({kind:'camera-grid',x:30,y:30,zoom:.8});ctx.present({kind:'build-tool',tool:'park'});return {prepared:true};}},
 map:{mode:'preview',fields:{x:{type:'integer',min:0,max:127},y:{type:'integer',min:0,max:127}},execute(p,ctx){hookMap=[p.x,p.y];ctx.notify('Point received');return {point:hookMap};}},
 status:{mode:'preview',fields:{},execute(){return {point:hookMap};}},
 review:{mode:'preview',fields:{},choiceFields:{name:{type:'string',maxLength:48}},execute(p,ctx){ctx.review(()=>showCustomEvent('CIVIC PROJECT','Hook review','Typed input remains on main until the opaque choice.',[{title:'Select ambition',apply:()=>{G.ambition=AMBITIONS[1].id;}}]));},settle(review,ctx){ctx.applyChoice(review,{validate:()=>review.payload.name==='town',verify:()=>G.ambition===AMBITIONS[1].id});}}
}});'''
code=base+extra
hook='''paused=true;window.hookProbe={fixture:()=>{seed(42);pendingEvent=null;return archivePayload();},state:()=>({frozen:Object.isFrozen(G),overlay,tool:buildMode,draft:{...draftPolicy}})};\n'''
bindings=[{'module':'hook-test','event':'click','selector':'#hookView','operation':'view','fields':{},'refresh':False},{'module':'hook-test','event':'map','tool':'park','operation':'map','fields':{'x':{'source':'tile-x','as':'integer'},'y':{'source':'tile-y','as':'integer'}}},{'module':'hook-test','event':'click','selector':'#hookReview','operation':'review','fields':{},'refresh':False},{'module':'hook-test','event':'choice','selector':'[data-worker-choice]','operation':'review','fields':{'name':{'source':'input','selector':'#hookName','as':'string'}}}]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':1000,'height':800});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.route('http://hook.test/',lambda r:r.fulfill(body=html,content_type='text/html'));p.goto('http://hook.test/');p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',bridge+hook+'// SOURCE: 99-instrumentation.js'));archive=p.evaluate('hookProbe.fixture()');p.evaluate('''()=>{for(const [id,text] of [['hookView','Review hooks'],['hookReview','Open review']]){const b=document.createElement('button');b.id=id;b.textContent=text;b.style='position:fixed;bottom:'+(id==='hookView'?20:60)+'px;right:20px;z-index:20000';document.body.appendChild(b);}const input=document.createElement('input');input.id='hookName';input.value='town';document.body.appendChild(input);}''');p.evaluate('''async a=>window.real=await __workerRealView.enable(a.code,a.archive,{routeBindings:a.bindings,initializeAuthority:async ask=>{const r=await ask({type:'initialize-command-owner'});if(!r.ordinaryDayReady)throw Error('Owner unavailable');}})''',{'code':code,'archive':archive,'bindings':bindings});p.locator('#hookView').click();p.evaluate('real.settlePanels()');p.evaluate('real.settleSaves()');state=p.evaluate('hookProbe.state()');assert state=={'frozen':True,'overlay':'roads','tool':'park','draft':{'minWage':14}},state;assert p.locator('#panelTitle').inner_text();p.mouse.click(450,350);p.evaluate('real.settlePanels()');p.evaluate('real.settleSaves()');point=p.evaluate('real.command({type:"route",module:"hook-test",operation:"status",payload:{}})')['paid']['value']['point'];assert point and len(point)==2
 p.locator('#hookReview').click();p.wait_for_function('document.querySelector("#eventDialog").style.display==="flex"');review=p.evaluate('real.command({type:"export"})');p.locator('[data-worker-choice]').first.click();p.wait_for_function('document.querySelector("#eventDialog").style.display==="none"');p.evaluate('real.settleSaves()');assert p.evaluate('hookProbe.state().frozen');assert not p.evaluate('real.recoveryStatus().faulted');assert not errors,errors
 Path('experimental/worker/route-ui-hooks-proof.json').write_text(json.dumps({'productionEnabled':False,'testOnlyModule':True,'sourceSha256':hashlib.sha256(source.encode()).hexdigest(),'workerSha256':hashlib.sha256(base.encode()).hexdigest(),'bridgeSha256':hashlib.sha256(bridge.encode()).hexdigest(),'trustedClickBinding':True,'typedPolicyCameraToolOverlayEffects':True,'trustedMapBinding':True,'opaqueChoiceTypedInputSettlement':True,'hostViewRemainsFrozen':True,'pageErrors':errors},indent=2)+'\n');print('PASS trusted declarative click/map, typed presentation and opaque choice input');b.close()
